import { Chart } from 'chart.js';
import { theme } from 'theme';

const DEFAULT_TOP_EXTENSION = 100;

const DEFAULT_AXIS_X_LEFT_EXTENSION = 100;
const DEFAULT_AXIS_X_RIGHT_EXTENSION = 100;

export interface VerticalGuidelinesProps {
  display?: boolean;
  displayLeftY?: boolean;
  displayRightY?: boolean;
  displayAxisX: boolean;
  color?: string;
  topExtension?: number;
  axisXLeftExtension?: number;
  axisXRightExtension?: number;
}

export const VerticalGuidelines = {
  id: 'verticalGuidelines',
  afterDraw: (chart: Chart) => {
    const { ctx, scales, config } = chart;

    const verticalGuidelinesPluginConfig =
      config.options?.plugins?.verticalGuidelines ?? {};

    if (verticalGuidelinesPluginConfig.display === false) return;

    const xAxis = scales.x;
    const yAxis = scales.y;

    if (!xAxis || !yAxis) return;

    const guidelineColor =
      verticalGuidelinesPluginConfig.color ||
      theme.colors.charts.bg.neutrals[40];
    const topExtension =
      verticalGuidelinesPluginConfig.topExtension ?? DEFAULT_TOP_EXTENSION;
    const axisXLeftExtension =
      verticalGuidelinesPluginConfig.axisXLeftExtension ??
      DEFAULT_AXIS_X_LEFT_EXTENSION;
    const axisXRightExtension =
      verticalGuidelinesPluginConfig.axisXRightExtension ??
      DEFAULT_AXIS_X_RIGHT_EXTENSION;

    const drawLine = (
      xStart: number,
      yStart: number,
      xEnd: number,
      yEnd: number,
      color: string | CanvasGradient | CanvasPattern,
    ) => {
      ctx.beginPath();
      ctx.moveTo(xStart, yStart);
      ctx.lineTo(xEnd, yEnd);
      ctx.lineWidth = 1;
      ctx.strokeStyle = color;
      ctx.stroke();
    };
    const plus =
      config.options?.indexAxis === 'y' &&
      !verticalGuidelinesPluginConfig.displayAxisX
        ? 30
        : 0;

    ctx.save();
    if (verticalGuidelinesPluginConfig.displayLeftY !== false) {
      drawLine(
        xAxis.left,
        yAxis.top - topExtension,
        xAxis.left,
        yAxis.bottom + plus,
        guidelineColor,
      );
    }

    if (
      config.options?.indexAxis === 'x' &&
      verticalGuidelinesPluginConfig.displayRightY !== false
    ) {
      drawLine(
        xAxis.right,
        yAxis.top - topExtension,
        xAxis.right,
        yAxis.bottom,
        guidelineColor,
      );
    }
    if (verticalGuidelinesPluginConfig.displayAxisX) {
      drawLine(
        xAxis.left - axisXLeftExtension,
        yAxis.bottom,
        xAxis.right + axisXRightExtension,
        yAxis.bottom,
        guidelineColor,
      );
    }

    ctx.restore();
  },
};
